import { MakeLogicType, afterMount, connect, kea, listeners, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { organizationLogic } from 'scenes/organizationLogic'

import type { OrganizationType } from '~/types'

import { dataFreshnessRetrieve } from 'products/platform_features/frontend/generated/api'
import type {
    DataFreshnessProjectApi,
    OrganizationDataFreshnessApi,
} from 'products/platform_features/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface projectDataFreshnessLogicValues {
    currentOrganization: OrganizationType | null // organizationLogic
    dataFreshness: OrganizationDataFreshnessApi | null
    dataFreshnessLoading: boolean
    freshnessByTeamId: Record<number, DataFreshnessProjectApi>
    lookbackDays: number
    quietAfterDays: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface projectDataFreshnessLogicActions {
    loadDataFreshness: () => any
    loadDataFreshnessFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadDataFreshnessSuccess: (
        dataFreshness: OrganizationDataFreshnessApi | null,
        payload?: any
    ) => {
        dataFreshness: OrganizationDataFreshnessApi | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface projectDataFreshnessLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        freshnessByTeamId: (
            dataFreshness: OrganizationDataFreshnessApi | null
        ) => Record<number, DataFreshnessProjectApi>
        quietAfterDays: (dataFreshness: OrganizationDataFreshnessApi | null) => number
        lookbackDays: (dataFreshness: OrganizationDataFreshnessApi | null) => number
    }
}

export type projectDataFreshnessLogicType = MakeLogicType<
    projectDataFreshnessLogicValues,
    projectDataFreshnessLogicActions,
    Record<string, any>,
    projectDataFreshnessLogicMeta
>

// Mirror posthog/data_freshness.py. Only used until the response lands, which carries the real values.
const DEFAULT_QUIET_AFTER_DAYS = 7
const DEFAULT_LOOKBACK_DAYS = 30

export const projectDataFreshnessLogic = kea<projectDataFreshnessLogicType>([
    path(['lib', 'components', 'Account', 'projectDataFreshnessLogic']),
    connect(() => ({
        values: [organizationLogic, ['currentOrganization']],
    })),
    loaders(({ values }) => ({
        dataFreshness: [
            null as OrganizationDataFreshnessApi | null,
            {
                loadDataFreshness: async (): Promise<OrganizationDataFreshnessApi | null> => {
                    if (!values.currentOrganization) {
                        return null
                    }
                    return await dataFreshnessRetrieve(values.currentOrganization.id)
                },
            },
        ],
    })),
    selectors({
        freshnessByTeamId: [
            (s) => [s.dataFreshness],
            (dataFreshness: OrganizationDataFreshnessApi | null): Record<number, DataFreshnessProjectApi> =>
                Object.fromEntries((dataFreshness?.results ?? []).map((result) => [result.team_id, result])),
        ],
        quietAfterDays: [
            (s) => [s.dataFreshness],
            (dataFreshness: OrganizationDataFreshnessApi | null): number =>
                dataFreshness?.quiet_after_days ?? DEFAULT_QUIET_AFTER_DAYS,
        ],
        lookbackDays: [
            (s) => [s.dataFreshness],
            (dataFreshness: OrganizationDataFreshnessApi | null): number =>
                dataFreshness?.lookback_days ?? DEFAULT_LOOKBACK_DAYS,
        ],
    }),
    listeners(({ actions }) => ({
        // The switcher can mount before the organization has loaded, in which case there are no
        // team IDs to ask about yet. Load on whichever of the two lands last.
        [organizationLogic.actionTypes.loadCurrentOrganizationSuccess]: () => {
            actions.loadDataFreshness()
        },
    })),
    afterMount(({ actions, values }) => {
        if (values.currentOrganization) {
            actions.loadDataFreshness()
        }
    }),
])
